window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3b39455b27363f66"]={"versions": [{"id": "FIG-3b39455b27363f66", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsszenario mit Objekterzeugung, Methodenaufrufen und kombiniertem Interaktionsfragment <code>loop</code>).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des Lebenszyklus und der Interaktionssequenz beim Senden unformatierter Datenströme (<em>Raw Data Stream</em>) über das Protokoll IEEE 1722 (<em>Audio Video Transport Protocol / AVTP</em>) innerhalb der AUTOSAR Adaptive Platform (ara::com / Raw Data Stream API).\n</li><li><strong>Funktionale Einordnung:</strong> Dient dem deterministischen, echtzeitnahen Streaming von AVB/TSN-Sensordaten (z. B. Video-, Audio- oder Radar-Streams) direkt aus einer <code>Adaptive Application</code> unter Umgehung des Service-Oriented-Communication-Overheads (SOME/IP), realisiert als spezialisierter Stream-Producer auf Plattformebene.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>:Adaptive Application</code>:</strong> Aktiver Prozess / Client-Instanz der Anwendungsdomäne, agiert als Initiator und Datenquelle des Datenstroms.\n</li><li><strong><code>:IEEE1722RawDataStreamProducer</code>:</strong> Plattform- bzw. Middleware-Entität (Endpunkt-Abstraktion der Raw Data Stream API), zuständig für die Kapselung, Header-Generierung (AVTP-Header, Stream-ID, Sequence-Numbering) und das Absenden der IEEE 1722-Frames über Ethernet/TSN-Sockets.\n</li><li><strong>Schnittstellen / Methoden:</strong>\n<ul class=\"fig-list\"><li><code>Create()</code>: Instanziierung / Allokation des Producer-Objekts (parametrisiert über Konfiguration/Manifest wie Stream-ID, VLAN, Traffic-Klasse).\n</li><li><code>Connect()</code>: Synchrone/asynchrone Bindung an das Netzwerkinterface bzw. Reservierung der TSN/AVB-Stream-Ressourcen.\n</li><li><code>WriteData()</code>: Übergabe des Daten-Payloads (Datagrams/Frames) an den Protokoll-Stack zur Übertragung.\n</li><li><code>Shutdown()</code>: Terminierung der Verbindung, Freigabe zugewiesener Descriptor- und Puffer-Ressourcen sowie Schließen des Socket-/TSN-Endpunkts.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Instanziierung:</strong> Die <code>Adaptive Application</code> erzeugt via <code>Create()</code> eine Instanz von <code>:IEEE1722RawDataStreamProducer</code>.\n</li><li><strong>Verbindungsaufbau:</strong> Aufruf von <code>Connect()</code>, um den Producer an das konfigurierte Netzwerkziel und die IEEE 1722 Stream-ID zu binden.\n</li><li><strong>Datenübertragung (<code>loop Write Data</code>):</strong>\n<ul class=\"fig-list\"><li>Wiederholter, zyklischer Aufruf von <code>WriteData()</code> innerhalb des Interaktionsfragments <code>loop</code>.\n</li><li>Payload wird serialisiert, in AVTP-Datagramme gepackt und versendet.\n</li></ul>\n</li><li><strong>Terminierung:</strong> Nach Abschluss der Datenübertragung ruft die Applikation <code>Shutdown()</code> auf.\n</li><li><strong>Objektzerstörung:</strong> Freigabe und Zerstörung des Producers (gekennzeichnet durch das Abbruch-/Lebensdauer-Ende-Kreuz <code>X</code> auf der Rettungsleine des <code>:IEEE1722RawDataStreamProducer</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Vertrag:</strong> <code>Connect()</code> muss zwingend vor dem ersten <code>WriteData()</code> erfolgreich ausgeführt worden sein. Ein Schreibversuch ohne aktiven Verbindungsstatus führt zu einem standardisierten Fehlercode (z. B. <code>ara::core::ErrorCode</code>).\n</li><li><strong>Pufferung &amp; Blocking-Semantik:</strong> <code>WriteData()</code> erfordert je nach Treiberkonfiguration entweder Zero-Copy-Pufferung (<code>ara::core::Span&lt;const uint8_t&gt;</code>) oder blockiert bei vollen Network-Socket-/TSN-Queue-Puffern. Entwickler müssen Pufferüberläufe und Timeouts bei hohen Datenraten (z. B. Rohkamera-Streams) über korrekte Socket-QoS/PBN-Konfigurationen absichern.\n</li><li><strong>Ressourcenfreigabe:</strong> <code>Shutdown()</code> ist vor der Deallokation des Application-Contexts zwingend erforderlich, um Leakage von File Descriptors, TSN-Bandbreitenreservierungen (Stream Reservation Protocol / IEEE 802.1Qat) und Socket-Handles im zugrunde liegenden POSIX-Betriebssystem zu verhindern.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-6f51fe889bf36180", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> UML-Sequenzdiagramm (Interaktionsszenario mit Objekterzeugung, Methodenaufrufen und kombiniertem Interaktionsfragment <code>loop</code>).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation des Lebenszyklus und der Interaktionssequenz beim Senden unformatierter Datenströme (<em>Raw Data Stream</em>) über das Protokoll IEEE 1722 (<em>Audio Video Transport Protocol / AVTP</em>) innerhalb der AUTOSAR Adaptive Platform (ara::com / Raw Data Stream API).\n</li><li><strong>Funktionale Einordnung:</strong> Dient dem deterministischen, echtzeitnahen Streaming von AVB/TSN-Sensordaten (z. B. Video-, Audio- oder Radar-Streams) direkt aus einer <code>Adaptive Application</code> unter Umgehung des Service-Oriented-Communication-Overheads (SOME/IP), realisiert als spezialisierter Stream-Producer auf Plattformebene.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong><code>:Adaptive Application</code>:</strong> Aktiver Prozess / Client-Instanz der Anwendungsdomäne, agiert als Initiator und Datenquelle des Datenstroms.\n</li><li><strong><code>:IEEE1722RawDataStreamProducer</code>:</strong> Plattform- bzw. Middleware-Entität (Endpunkt-Abstraktion der Raw Data Stream API), zuständig für die Kapselung, Header-Generierung (AVTP-Header, Stream-ID, Sequence-Numbering) und das Absenden der IEEE 1722-Frames über Ethernet/TSN-Sockets.\n</li><li><strong>Schnittstellen / Methoden:</strong>\n<ul class=\"fig-list\"><li><code>Create()</code>: Instanziierung / Allokation des Producer-Objekts (parametrisiert über Konfiguration/Manifest wie Stream-ID, VLAN, Traffic-Klasse).\n</li><li><code>Connect()</code>: Synchrone/asynchrone Bindung an das Netzwerkinterface bzw. Reservierung der TSN/AVB-Stream-Ressourcen.\n</li><li><code>WriteData()</code>: Übergabe des Daten-Payloads (Datagrams/Frames) an den Protokoll-Stack zur Übertragung.\n</li><li><code>Shutdown()</code>: Terminierung der Verbindung, Freigabe zugewiesener Descriptor- und Puffer-Ressourcen sowie Schließen des Socket-/TSN-Endpunkts.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Instanziierung:</strong> Die <code>Adaptive Application</code> erzeugt via <code>Create()</code> eine Instanz von <code>:IEEE1722RawDataStreamProducer</code>.\n</li><li><strong>Verbindungsaufbau:</strong> Aufruf von <code>Connect()</code>, um den Producer an das konfigurierte Netzwerkziel und die IEEE 1722 Stream-ID zu binden.\n</li><li><strong>Datenübertragung (<code>loop Write Data</code>):</strong>\n<ul class=\"fig-list\"><li>Wiederholter, zyklischer Aufruf von <code>WriteData()</code> innerhalb des Interaktionsfragments <code>loop</code>.\n</li><li>Payload wird serialisiert, in AVTP-Datagramme gepackt und versendet.\n</li></ul>\n</li><li><strong>Terminierung:</strong> Nach Abschluss der Datenübertragung ruft die Applikation <code>Shutdown()</code> auf.\n</li><li><strong>Objektzerstörung:</strong> Freigabe und Zerstörung des Producers (gekennzeichnet durch das Abbruch-/Lebensdauer-Ende-Kreuz <code>X</code> auf der Rettungsleine des <code>:IEEE1722RawDataStreamProducer</code>).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>API-Vertrag:</strong> <code>Connect()</code> muss zwingend vor dem ersten <code>WriteData()</code> erfolgreich ausgeführt worden sein. Ein Schreibversuch ohne aktiven Verbindungsstatus führt zu einem standardisierten Fehlercode (z. B. <code>ara::core::ErrorCode</code>).\n</li><li><strong>Pufferung &amp; Blocking-Semantik:</strong> <code>WriteData()</code> erfordert je nach Treiberkonfiguration entweder Zero-Copy-Pufferung (<code>ara::core::Span&lt;const uint8_t&gt;</code>) oder blockiert bei vollen Network-Socket-/TSN-Queue-Puffern. Entwickler müssen Pufferüberläufe und Timeouts bei hohen Datenraten (z. B. Rohkamera-Streams) über korrekte Socket-QoS/PBN-Konfigurationen absichern.\n</li><li><strong>Ressourcenfreigabe:</strong> <code>Shutdown()</code> ist vor der Deallokation des Application-Contexts zwingend erforderlich, um Leakage von File Descriptors, TSN-Bandbreitenreservierungen (Stream Reservation Protocol / IEEE 802.1Qat) und Socket-Handles im zugrunde liegenden POSIX-Betriebssystem zu verhindern.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-3b39455b27363f66", "to": "FIG-6f51fe889bf36180", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
